style.css:
@-moz-document domain("youtube.com") {
/* ===== Sleek Black ===== */

:root{
  --bg:#090909;
  --surface:#121212;
  --surface-hover:#1a1a1a;
  --border:#2a2a2a;
  --radius:20px;
}

/* Background */
html,
body,
ytd-app{
  background:var(--bg)!important;
}

/* Top bar */
#masthead-container{
  background:rgba(9,9,9,.82)!important;
  backdrop-filter:blur(8px)!important;
  -webkit-backdrop-filter:blur(8px)!important;
  border-bottom:1px solid rgba(255,255,255,.05)!important;
}

/* Search */
#search-form{
  background:var(--surface)!important;
  border:1px solid var(--border)!important;
  border-radius:999px!important;
}

/* Sidebar */
#guide-content{
  background:transparent!important;
}

/* Cards */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer{

  background:var(--surface)!important;
  border:1px solid var(--border)!important;
  border-radius:20px!important;

  transition:
  transform .28s cubic-bezier(.22,1,.36,1),
  background .28s,
  border-color .28s,
  box-shadow .28s!important;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover{

  transform:
    translateY(-3px)
    scale(1.015);

  background:var(--surface-hover)!important;

  border-color:#444!important;

  box-shadow:
    0 18px 40px rgba(0,0,0,.28);
}

/* Thumbnails */

ytd-thumbnail img{
  border-radius:18px!important;
  transition:transform .3s cubic-bezier(.22,1,.36,1)!important;
}

ytd-rich-item-renderer:hover img,
ytd-video-renderer:hover img{
  transform:scale(1.04);
}

/* Buttons */

button,
.ytp-button{

  border-radius:14px!important;

  transition:
  transform .2s cubic-bezier(.22,1,.36,1),
  background .2s!important;
}

button:hover,
.ytp-button:hover{

  transform:scale(1.05);

  background:#242424!important;
}

/* Scrollbar */

::-webkit-scrollbar{
  width:8px;
}

::-webkit-scrollbar-thumb{

  background:#383838;

  border-radius:999px;
}

::-webkit-scrollbar-thumb:hover{
  background:#5b5b5b;
}

/* Smooth */

*{
  transition:
  background-color .22s,
  border-color .22s,
  transform .22s cubic-bezier(.22,1,.36,1),
  opacity .18s!important;
}
}
